using System;
using System.Collections.Generic;
using Game.Vehicle.Physics;
using UnityEngine;

namespace Game.Vehicle.Runtime
{
    /// <summary>
    /// References the authoritative JSON definitions (Vehicle/Physics/Definitions/Data/*.json, owned by
    /// vehicle-physics) so that they ship in the player. Parsed with <see cref="JsonUtility"/> (the definition
    /// classes use plain public fields). Generated by the DrivingLab editor builder; the default instance lives
    /// in Resources so tests and runtime code can find it.
    /// </summary>
    [CreateAssetMenu(menuName = "Kamion/Vehicle Data", fileName = "VehicleData")]
    public sealed class VehicleDataAsset : ScriptableObject
    {
        public const string DefaultResourcePath = "VehicleData_Tractor4x2";

        public TextAsset vehicle;
        public TextAsset engine;
        public TextAsset gearbox;
        public TextAsset[] tires = new TextAsset[0];

        [NonSerialized] VehicleDefinition m_Vehicle;
        [NonSerialized] EngineDefinition m_Engine;
        [NonSerialized] GearboxDefinition m_Gearbox;
        [NonSerialized] Dictionary<string, TireDefinition> m_Tires;

        public static VehicleDataAsset LoadDefault()
        {
            var a = Resources.Load<VehicleDataAsset>(DefaultResourcePath);
            if (a == null) throw new InvalidOperationException($"Resources/{DefaultResourcePath} missing (run Kamion/Setup/Rebuild DrivingLab)");
            return a;
        }

        public VehicleDefinition Vehicle { get { Parse(); return m_Vehicle; } }

        /// <summary>Creates a fresh solver instance (new state). Definitions are parsed once and shared.</summary>
        public VehicleModel CreateModel(SolverSettings settings = null)
        {
            Parse();
            return new VehicleModel(m_Vehicle, m_Engine, m_Gearbox, m_Tires, settings);
        }

        void Parse()
        {
            if (m_Vehicle != null) return;
            if (vehicle == null || engine == null || gearbox == null || tires == null || tires.Length == 0)
                throw new InvalidOperationException($"{name}: definition TextAssets not assigned");
            var v = JsonUtility.FromJson<VehicleDefinition>(vehicle.text);
            v.Validate();
            var e = JsonUtility.FromJson<EngineDefinition>(engine.text);
            e.Validate();
            var g = JsonUtility.FromJson<GearboxDefinition>(gearbox.text);
            g.Validate();
            var t = new Dictionary<string, TireDefinition>();
            foreach (var ta in tires)
            {
                var td = JsonUtility.FromJson<TireDefinition>(ta.text);
                td.Validate();
                t[td.id] = td;
            }
            if (v.engineId != e.id) throw new FormatException($"{name}: vehicle wants engine '{v.engineId}', got '{e.id}'");
            if (v.gearboxId != g.id) throw new FormatException($"{name}: vehicle wants gearbox '{v.gearboxId}', got '{g.id}'");
            m_Vehicle = v; m_Engine = e; m_Gearbox = g; m_Tires = t;
        }

        void OnValidate() { m_Vehicle = null; }
    }
}
